INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine Auswahl in einer Datenbank immer nur eine Spalte betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Kann mehrere Spalten umfassen"}, {"text": "Ja", "correct": false, "because": "Mehrere Spalten möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche SQL-Anweisung wird für die Datenauswahl verwendet?', 3, '[{"text": "SELECT", "correct": true, "because": "Wählt Daten aus Tabellen"}, {"text": "INSERT", "correct": false, "because": "Fügt Daten ein"}, {"text": "DELETE", "correct": false, "because": "Löscht Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Auswahl in Algorithmen?', 5, '[{"text": "Kriterien", "correct": true, "because": "Bestimmen Relevanz"}, {"text": "Effizienz", "correct": true, "because": "Beeinflusst Laufzeit"}, {"text": "Datenqualität", "correct": true, "because": "Sichert Ergebnisse"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Auswahlfaktor"}, {"text": "Bildschirmgröße", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) WHERE schränkt die Datenauswahl ein. b) Es wählt immer alle Zeilen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, WHERE filtert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Datenauswahl in einer Datenbank?', 4, '[{"text": "Bedingungen", "correct": false, "because": "Definieren Auswahl"}, {"text": "Spalten", "correct": false, "because": "Bestimmen Inhalt"}, {"text": "Tabellenfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine Auswahl immer deterministisch ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kann zufällig sein"}, {"text": "Ja", "correct": false, "because": "Nicht immer deterministisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Klausel in SQL verfeinert die Datenauswahl?', 4, '[{"text": "WHERE", "correct": true, "because": "Filtert nach Bedingungen"}, {"text": "INSERT", "correct": false, "because": "Fügt Daten ein"}, {"text": "UPDATE", "correct": false, "because": "Ändert Daten"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Auswahlprozesse in Algorithmen immer linear sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Können auch binär sein"}, {"text": "Ja", "correct": false, "because": "Verschiedene Ansätze"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Wählt SELECT * alle Spalten?', 2, '[{"text": "Ja", "correct": true, "because": "Holt alle Spalten"}, {"text": "Nein", "correct": false, "because": "Standardverhalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien sind für die Auswahl von Personal wichtig?', 5, '[{"text": "Qualifikation", "correct": true, "because": "Bestimmt Eignung"}, {"text": "Erfahrung", "correct": true, "because": "Zeigt Praxis"}, {"text": "Kleidungsstil", "correct": false, "because": "Sekundär"}, {"text": "Bürogestaltung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer Datenbankauswahl?', 4, '[{"text": "Relevante Daten", "correct": true, "because": "Sichert Nutzen"}, {"text": "Maximale Zeilen", "correct": false, "because": "Ineffizient"}, {"text": "Tabellenfarbe", "correct": false, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) ORDER BY sortiert die Auswahl. b) Es wählt immer zufällig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Sortierung gezielt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine gezielte Datenauswahl?', 3, '[{"text": "Filterbedingungen", "correct": false, "because": "Verfeinern Auswahl"}, {"text": "Spaltenangaben", "correct": false, "because": "Bestimmen Inhalt"}, {"text": "Diagrammfarben", "correct": true, "because": "Kein Auswahlfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich in SQL nach bestimmten Daten filtere?', 4, '[{"text": "Mit WHERE und Bedingungen", "correct": true, "because": "Grenzt Daten ein"}, {"text": "Nur mit SELECT", "correct": false, "because": "Zu allgemein"}, {"text": "Ohne Filter", "correct": false, "because": "Unpräzise"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Auswahl in Algorithmen immer schnell ist. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Abhängig von Datenmenge"}, {"text": "Ja", "correct": false, "because": "Komplexität variiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip verbessert die Effizienz der Datenauswahl?', 4, '[{"text": "Indizierung", "correct": true, "because": "Beschleunigt Abfragen"}, {"text": "Zufällige Suche", "correct": false, "because": "Ineffizient"}, {"text": "Maximaler Speicher", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Wählt GROUP BY einzelne Zeilen?', 2, '[{"text": "Nein", "correct": true, "because": "Gruppiert Daten"}, {"text": "Ja", "correct": false, "because": "Für Aggregation"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine gezielte Datenauswahl?', 5, '[{"text": "Effizienz", "correct": true, "because": "Reduziert Verarbeitung"}, {"text": "Präzision", "correct": true, "because": "Liefert relevante Daten"}, {"text": "Bunte Visuals", "correct": false, "because": "Kein Auswahlfaktor"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Auswahl von Personal unwichtig?', 3, '[{"text": "Kompetenzen", "correct": false, "because": "Bestimmen Eignung"}, {"text": "Motivation", "correct": false, "because": "Beeinflusst Leistung"}, {"text": "Schriftart des Lebenslaufs", "correct": true, "because": "Kosmetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich Daten in einer Datenbank auswähle?', 4, '[{"text": "SELECT mit WHERE filtern", "correct": true, "because": "Zielgerichtete Abfrage"}, {"text": "Nur INSERT nutzen", "correct": false, "because": "Fügt Daten ein"}, {"text": "Ohne Bedingung", "correct": false, "because": "Unpräzise"}]');
